M="nephron-pathway"
SUB="Physiology"
T={
"tracker":[("Which nephron segment reabsorbs the largest fraction of filtered Mg²⁺?",["Thick ascending limb","Proximal tubule","Distal convoluted tubule","Collecting duct"],0,"About 60–70% of filtered Mg²⁺ is reabsorbed paracellularly in the TAL; the PCT takes only ~15–25%."),
 ("Which substance is normally both filtered and secreted by the proximal tubule, so its clearance exceeds GFR?",["PAH","Inulin","Glucose","Albumin"],0,"PAH is filtered and secreted by organic anion transporters; inulin is filtered only, glucose is fully reabsorbed."),
 ('In a research study, a healthy 25-year-old man receives a constant infusion of para-aminohippurate at a low plasma concentration. Its clearance is 625 mL/min, while inulin clearance is 120 mL/min. The PAH clearance best estimates his:', ['Effective renal plasma flow', 'Glomerular filtration rate', 'Total renal blood flow', 'Filtration fraction'], 0, 'PAH is filtered and almost completely secreted, so its clearance ≈ effective renal plasma flow; GFR is the inulin value and RBF = RPF/(1 − Hct).', 2)],
"pt1":[("The early proximal tubule reabsorbs Na⁺ mainly together with:",["Glucose, amino acids, phosphate, HCO₃⁻","K⁺ and 2Cl⁻ through NKCC2","Cl⁻ through the thiazide-sensitive NCC","Water through ADH-regulated AQP2"],0,"Early PCT: Na⁺ cotransport with organic solutes and Na⁺/H⁺ exchange (HCO₃⁻ reclaim); Cl⁻ follows later."),
 ("Fluid leaving the proximal tubule, compared with plasma, is:",["Isosmotic","Hyposmotic","Hyperosmotic","Variable with ADH"],0,"Water follows solute through AQP1, so ~65% of filtrate is reabsorbed isosmotically."),
 ('An 8-year-old boy has bowed legs and poor growth. Labs: plasma glucose 90 mg/dL with 2+ glucosuria, generalized aminoaciduria, phosphaturia, serum phosphate 2.1 mg/dL and serum HCO₃⁻ 16 mEq/L with normal anion gap. Which nephron segment is dysfunctional?', ['Proximal convoluted tubule', 'Thick ascending limb', 'Distal convoluted tubule', 'Medullary collecting duct'], 0, 'Fanconi syndrome: global loss of proximal Na⁺-coupled reabsorption (glucose, amino acids, phosphate, HCO₃⁻) causing hypophosphatemic rickets and type 2 RTA; distal segments do not handle these solutes.', 2)],
"tal":[("The thick ascending limb is called the diluting segment because it:",["Reabsorbs NaCl but is impermeable to water","Secretes free water into the lumen","Reabsorbs urea via UT-A transporters","Responds to ADH by inserting AQP2"],0,"NKCC2 moves NaCl out while water cannot follow, so tubular fluid becomes hypotonic.",2),
 ("A drug that blocks NKCC2 in the TAL would increase urinary loss of:",["Ca²⁺ and Mg²⁺","Glucose and amino acids","Glucose and phosphate","HCO₃⁻ and citrate"],0,"Loss of the lumen-positive voltage stops paracellular Ca²⁺ and Mg²⁺ reabsorption (loop diuretics).",2)],
"dct":[("Ca²⁺ reabsorption in the distal convoluted tubule is increased by:",["PTH","Aldosterone","ANP","Furosemide"],0,"PTH acts on the DCT to increase transcellular Ca²⁺ reabsorption."),
 ("The Na⁺ transporter in the apical membrane of the early DCT is:",["Na⁺–Cl⁻ cotransporter (NCC)","Na⁺–K⁺–2Cl⁻ cotransporter (NKCC2)","Epithelial Na⁺ channel (ENaC)","Na⁺/H⁺ exchanger (NHE3)"],0,"NCC is the target of thiazides; ENaC is in principal cells."),
 ('A 22-year-old woman has recurrent muscle cramps. BP 108/68 mm Hg. Serum K⁺ 2.9 mEq/L, Mg²⁺ 1.2 mg/dL, HCO₃⁻ 31 mEq/L; urinary calcium is low. She takes no medications. A mutation most likely affects the:', ['Na⁺–Cl⁻ cotransporter (NCC)', 'Na⁺–K⁺–2Cl⁻ cotransporter (NKCC2)', 'Epithelial Na⁺ channel (ENaC)', 'Na⁺/H⁺ exchanger (NHE3)'], 0, 'Gitelman syndrome mimics a thiazide: hypokalemic alkalosis, hypomagnesemia and hypocalciuria from loss of DCT NCC. Bartter (NKCC2) causes hypercalciuria instead.', 3)],
"pc":[("Aldosterone increases K⁺ secretion by principal cells mainly by:",["Increasing ENaC and Na⁺/K⁺-ATPase","Inserting AQP2 water channels","Activating apical H⁺-ATPase","Blocking apical ROMK channels"],0,"More Na⁺ entry makes the lumen negative and more K⁺ is pumped into the cell, driving K⁺ out through ROMK.",2),
 ("Amiloride causes hyperkalemia because it blocks:",["ENaC in principal cells","NCC in the DCT","NKCC2 in the TAL","Carbonic anhydrase in the PCT"],0,"Less Na⁺ entry reduces the lumen-negative potential that drives K⁺ secretion.")],
"mcd":[("In the presence of ADH, the inner medullary collecting duct reabsorbs urea through:",["UT-A1 and UT-A3 transporters","NKCC2 and NCC cotransporters","ENaC and ROMK channels","AQP1 water channels"],0,"ADH-stimulated urea recycling builds the medullary osmotic gradient."),
 ("A patient lacking ADH produces urine with an osmolality closest to:",["50–100 mOsm/kg","300 mOsm/kg","600 mOsm/kg","1200 mOsm/kg"],0,"Without ADH the collecting duct stays water-impermeable and dilute fluid from the TAL is excreted.",2)],
}
